import{_ as r,a0 as i,w as l,s as p,I as s,x as d,a1 as o,A as a,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"15 个提高工作效率的 VS Code 键盘快捷键 | LCTT x X-CMD","titleTemplate":false,"description":"15 个提高工作效率的 VS Code 键盘快捷键 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"15 个提高工作效率的 VS Code 键盘快捷键 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"15 个提高工作效率的 VS Code 键盘快捷键 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210605 15 Useful Visual Studio Code Keyboard Shortcuts to Increase Productivity","title":"15 个提高工作效率的 VS Code 键盘快捷键","tag":"202106","desc":""},"relativePath":"202106/20210605 15 Useful Visual Studio Code Keyboard Shortcuts to Increase Productivity.md","filePath":"[post].md"}'),n={name:"202106/20210605 15 Useful Visual Studio Code Keyboard Shortcuts to Increase Productivity.md"};function h(m,t,b,u,C,f){const e=i("Link");return l(),p("div",null,[t[28]||(t[28]=s("h1",{id:"_15-个提高工作效率的-vs-code-键盘快捷键",tabindex:"-1"},[d("15 个提高工作效率的 VS Code 键盘快捷键 "),s("a",{class:"header-anchor",href:"#_15-个提高工作效率的-vs-code-键盘快捷键","aria-label":"Permalink to “15 个提高工作效率的 VS Code 键盘快捷键”"},"​")],-1)),t[29]||(t[29]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202106/13/123502pqfi45mgpf8847yf.jpg",alt:""})],-1)),s("p",null,[t[1]||(t[1]=d("毫无疑问，微软的 ",-1)),o(e,{href:"https://itsfoss.com/best-modern-open-source-code-editors-for-linux/"},{default:a(()=>[...t[0]||(t[0]=[d("VS Code是最好的开源代码编辑器之一",-1)])]),_:1}),t[2]||(t[2]=d("。它与传说中的 Vim 不同，VS Code 不需要你是一个快捷键大师（LCTT 译注：以下都指键盘快捷键），开发者们对它大部分的功能都及其熟悉，且推崇备至。",-1))]),t[30]||(t[30]=c('<p>但这并不意味着你不能成为快捷键大师，或者说你在 VS Code 中不应该使用快捷键。</p><p>在敲代码的时候，你可能需要用鼠标去执行其他的动作，比如在 VS Code 编辑器中切换终端，而此时你的代码流程会被打断，这是不是很讨厌？如果是的，那么你应该立即熟记下面这些 VS Code 有用的快捷键。</p><p>它不仅能帮助你摆脱鼠标，还能使你的生产力和工作效率得到提高。</p><p>那么，让我们来了解一下如何通过使用快捷键快速进行代码导航来进行快速编码。</p><h3 id="有用的-vs-code-快捷键" tabindex="-1">有用的 VS Code 快捷键 <a class="header-anchor" href="#有用的-vs-code-快捷键" aria-label="Permalink to “有用的 VS Code 快捷键”">​</a></h3><p>免责声明。下面的这些快捷键是我在 VS Code 的使用中发现的较为有用的，你可以根据你的需要来发现更多有用的快捷键。</p><p>下面我还给出了 MacOS 用户的键盘快捷键。</p><h4 id="_1、显示所有命令" tabindex="-1">1、显示所有命令 <a class="header-anchor" href="#_1、显示所有命令" aria-label="Permalink to “1、显示所有命令”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + SHIFT + P</code> 或 <code>F1</code></td><td><code>SHIFT + ⌘ + P</code> 或 <code>F1</code></td></tr></tbody></table></div><p>我们从最有用的快捷键开始，这个快捷键能打开命令面板（列表），它提供了对 VS Code 所有功能的访问。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/Command-Palette.jpg?resize=800%2C418&amp;ssl=1" alt="命令面板"></p><p>这是一个非常重要的 VS Code 快捷键，因为即使你忘记了或不想记起其他任何快捷键，但你记得这个，那么你仍然可以使用命令面板进行各种操作，如创建新文件、打开设置、改变主题，还可以查看所有快捷键。</p><h4 id="_2、垂直和水平拆分-vs-code-编辑器" tabindex="-1">2、垂直和水平拆分 VS Code 编辑器 <a class="header-anchor" href="#_2、垂直和水平拆分-vs-code-编辑器" aria-label="Permalink to “2、垂直和水平拆分 VS Code 编辑器”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + \\</code></td><td><code>⌘ + \\</code></td></tr></tbody></table></div><p>为了提高效率，但你又没有安装多个显示器，那么你可以通过水平或垂直分割 VS Code 的编辑器来一次查看多个文件的代码。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/05/Split-VS-Code.png?resize=800%2C405&amp;ssl=1" alt="分割 VS Code 编辑区"></p><p>要在多个编辑区间切换焦点，你可以使用数字键或箭头键。</p><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + 1</code>/<code>2</code>/<code>3</code></td><td><code>⌘ + 1</code>/<code>2</code>/<code>3</code></td></tr><tr><td><code>CTRL + K</code> <code>CTRL + ←</code>/<code>→</code></td><td><code>⌘ + K</code> <code>⌘ + ←</code>/<code>→</code></td></tr></tbody></table></div><h4 id="_3、切换集成终端" tabindex="-1">3、切换集成终端 <a class="header-anchor" href="#_3、切换集成终端" aria-label="Permalink to “3、切换集成终端”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td>CTRL + `</td><td>⌘ + `</td></tr></tbody></table></div><p>VS Code 中的集成终端是一个非常方便的功能，它可以让你在不切换窗口的情况下快速执行任务。要在编辑器中显示/隐藏终端，下面的快捷键会非常方便。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/Integrated-Terminal.png?resize=800%2C221&amp;ssl=1" alt="集成终端"></p><p>但是，如果你跟我一样觉得 CTRL + ` 在键盘的角落位置而比较难按到，你可以打开命令面板执行<code>View: Toggle Terminal</code> 命令来切换终端。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/05/Toggle-Terminal-Using-Command-Palette.png?resize=686%2C118&amp;ssl=1" alt="使用命令面板切换终端"></p><h4 id="_4、转到文件" tabindex="-1">4、转到文件 <a class="header-anchor" href="#_4、转到文件" aria-label="Permalink to “4、转到文件”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + P</code></td><td><code>⌘ + P</code></td></tr></tbody></table></div><p>随着项目的壮大，查找文件可能会变得困难。因此，我建议，即使你使用鼠标，这个命令也能为你节省很多搜索和导航到版本库中的文件的时间。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/05/Go-to-file.jpg?resize=800%2C388&amp;ssl=1" alt="转到文件"></p><h4 id="_5、转到行" tabindex="-1">5、转到行 <a class="header-anchor" href="#_5、转到行" aria-label="Permalink to “5、转到行”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + G</code></td><td><code>^ + G</code></td></tr></tbody></table></div><p>当你找到文件，你可能需要去到文件中指定的行增加或编辑代码，而如果这个文件包含了数千行代码，那么滚动代码将会浪费你大量的时间。而 <code>CTRL + G</code> 或 <code>^ + G</code> 快捷键能让你快速的去掉指定的行。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/Go-to-line.jpg?resize=800%2C99&amp;ssl=1" alt="转到行"></p><p>另外，你也可以使用上面的转到文件的快捷键，在输入框中输入冒号 <code>:</code> 加行号，结果就跟转到行是一样的。</p><h4 id="_6、在整个项目中搜索" tabindex="-1">6、在整个项目中搜索 <a class="header-anchor" href="#_6、在整个项目中搜索" aria-label="Permalink to “6、在整个项目中搜索”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + SHIFT + F</code></td><td><code>⌘ + SHIFT + F</code></td></tr></tbody></table></div><p>很可能你需要在整个项目中搜索一个文本、变量或函数，在这种情况下，上面的命令就非常方便，它会在侧边栏显示一个搜索输入框。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/05/Search-project.jpg?resize=381%2C450&amp;ssl=1" alt="在项目中搜索"></p><p>我们还可以在搜索的时候添加一些过滤器，比如使用 <code>ALT+C</code> 来启用大写匹配，<code>ALT+W</code> 用于匹配整个单词，<code>ALT+R</code> 用于启用正则表达式。</p><h4 id="_7、禅模式" tabindex="-1">7、禅模式 <a class="header-anchor" href="#_7、禅模式" aria-label="Permalink to “7、禅模式”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + K Z</code></td><td><code>⌘ + K Z</code></td></tr></tbody></table></div><p>想要在不受干扰的环境中工作以保持更专注？ 你可以试试禅模式（先按下 <code>CTRL + K</code>，再按下 <code>Z</code>），它会隐藏所有 UI（状态栏、活动栏、面板和侧边栏）并仅在全屏上显示编辑器。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/05/Zen-Mode.png?resize=800%2C450&amp;ssl=1" alt="禅模式"></p><p>要启用禅模式，你可以使用上面的快捷键或者打开命令面板执行 <code>View: Toggle Zen Mode</code>，要退出禅模式，你可以按两次 <code>Esc</code> 键。</p><h4 id="_8、将选择添加到下一次匹配中" tabindex="-1">8、将选择添加到下一次匹配中 <a class="header-anchor" href="#_8、将选择添加到下一次匹配中" aria-label="Permalink to “8、将选择添加到下一次匹配中”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + D</code></td><td><code>⌘ + D</code></td></tr></tbody></table></div><p>这条命令能让你选择所选文本的下一个出现的地方，从而进行编辑。如果下一个匹配出现的位置与第一个相离较远，那这将会很方便处理。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/05/Next-find-match.jpg?resize=800%2C313&amp;ssl=1" alt="查找下一个匹配"></p><h4 id="_9、切换行注释" tabindex="-1">9、切换行注释 <a class="header-anchor" href="#_9、切换行注释" aria-label="Permalink to “9、切换行注释”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + /</code></td><td><code>⌘ + /</code></td></tr></tbody></table></div><p>将光标移到行的开头，然后添加双斜杠进行注释，这种麻烦的操作我们可以用上面的快捷键来代替了。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/Comment-out-code.jpg?resize=800%2C313&amp;ssl=1" alt="注释代码"></p><p>甚至，如果你想注释多行代码，你可以先通过 <code>SHIFT+UP</code>/<code>Down</code> 快捷键来选中多行，然后按 <code>CTRL+/</code> 快捷键进行注释。</p><h4 id="_10、转到文件的开头或结尾" tabindex="-1">10、转到文件的开头或结尾 <a class="header-anchor" href="#_10、转到文件的开头或结尾" aria-label="Permalink to “10、转到文件的开头或结尾”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + HOME</code>/<code>END</code></td><td><code>⌘ + ↑</code>/<code>↓</code></td></tr></tbody></table></div><p>如果你迷失在文件的中间位置，该命令可以让你快速达到文件的起点或终点。</p><h4 id="_11、代码折叠或打开" tabindex="-1">11、代码折叠或打开 <a class="header-anchor" href="#_11、代码折叠或打开" aria-label="Permalink to “11、代码折叠或打开”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + SHIFT + [</code>/<code>]</code></td><td><code>⌥ + ⌘ + [</code>/<code>]</code></td></tr></tbody></table></div><p>这也是最有用的快捷键之一，它可以帮助你折叠/取消折叠一个区域的代码。通过这种方式，你可以隐藏不必要的代码，每次只查看所需的部分代码，以便更加专注和快速编码。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/05/Collapse-a-region-of-code.jpg?resize=800%2C287&amp;ssl=1" alt="折叠一块代码"></p><h4 id="_12、窥视执行" tabindex="-1">12、窥视执行 <a class="header-anchor" href="#_12、窥视执行" aria-label="Permalink to “12、窥视执行”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + SHIFT + F12</code></td><td><code>⌘ + SHIFT + F12</code></td></tr></tbody></table></div><p>这个快捷键最有可能的作用是帮助你进行代码分析，或修复 bug 时了解函数和变量的运行情况。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/05/Peek-Implementation.png?resize=800%2C339&amp;ssl=1" alt="窥视执行"></p><h4 id="_13、删除当前行" tabindex="-1">13、删除当前行 <a class="header-anchor" href="#_13、删除当前行" aria-label="Permalink to “13、删除当前行”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + SHIFT + K</code></td><td><code>SHIFT + ⌘ + K</code></td></tr></tbody></table></div><p>这是一条可以快速执行，选中当前行并按删除/退格键，这两个任务的简单命令。</p><h4 id="_14、查找与替换" tabindex="-1">14、查找与替换 <a class="header-anchor" href="#_14、查找与替换" aria-label="Permalink to “14、查找与替换”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + F</code></td><td><code>⌘ + F</code></td></tr><tr><td><code>CTRL + H</code></td><td><code>⌥ + ⌘ + F</code></td></tr></tbody></table></div><p>用一个新的文本替换文件中所有出现的该文本的最好方法是什么？如果你手动一个一个的通过滚动代码来处理，且如果需要替换的地方又很多，那么你可能会花费大量的时间。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/05/Find-and-replace.png?resize=800%2C223&amp;ssl=1" alt="查找与替换"></p><p>而使用查找和替换功能我们能在几秒内完成相同的任务。你可以用两个快捷键来打开它，其中一个实际上是打开用于查找文本的输入框，另一个用于输入新的文本。</p><h4 id="_15、vs-code-的全部键盘快捷键" tabindex="-1">15、VS Code 的全部键盘快捷键 <a class="header-anchor" href="#_15、vs-code-的全部键盘快捷键" aria-label="Permalink to “15、VS Code 的全部键盘快捷键”">​</a></h4><div class="table-wrap"><table><thead><tr><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td><code>CTRL + K CTRL + S</code></td><td><code>⌘ + K ⌘ + S</code></td></tr></tbody></table></div><p>最后，如果你还在为记住上述所有的快捷键而苦恼，你大可不必。因为你可以使用上面的快捷键查看编辑器所有可用的命令。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/05/Keyboard-Shortcuts.png?resize=800%2C406&amp;ssl=1" alt="快捷键"></p><p>你还可以根据自己的喜好编辑命令的绑定键。</p><h3 id="想要为-vs-code-添加更多快捷键" tabindex="-1">想要为 VS Code 添加更多快捷键？ <a class="header-anchor" href="#想要为-vs-code-添加更多快捷键" aria-label="Permalink to “想要为 VS Code 添加更多快捷键？”">​</a></h3>',77)),s("p",null,[t[4]||(t[4]=d("如果你想对 VS Code 的快捷键有完整的了解，你可以查看 VS Code 的 ",-1)),o(e,{href:"https://code.visualstudio.com/docs/getstarted/keybindings"},{default:a(()=>[...t[3]||(t[3]=[d("文档",-1)])]),_:1}),t[5]||(t[5]=d("。",-1))]),s("p",null,[t[9]||(t[9]=d("或者，如果你想在纸上将所有快捷键打印出来慢慢看，下面这些是各个系统对应的快捷键速查表： ",-1)),o(e,{href:"https://code.visualstudio.com/shortcuts/keyboard-shortcuts-linux.pdf"},{default:a(()=>[...t[6]||(t[6]=[d("Linux",-1)])]),_:1}),t[10]||(t[10]=d("、",-1)),o(e,{href:"https://code.visualstudio.com/shortcuts/keyboard-shortcuts-macos.pdf"},{default:a(()=>[...t[7]||(t[7]=[d("macOS",-1)])]),_:1}),t[11]||(t[11]=d(" 和 ",-1)),o(e,{href:"https://code.visualstudio.com/shortcuts/keyboard-shortcuts-windows.pdf"},{default:a(()=>[...t[8]||(t[8]=[d("Windows",-1)])]),_:1}),t[12]||(t[12]=d("。",-1))]),t[31]||(t[31]=s("hr",null,null,-1)),s("p",null,[t[14]||(t[14]=d("via: ",-1)),o(e,{href:"https://itsfoss.com/vs-code-shortcuts/"},{default:a(()=>[...t[13]||(t[13]=[d("https://itsfoss.com/vs-code-shortcuts/",-1)])]),_:1})]),s("p",null,[t[19]||(t[19]=d("作者：",-1)),o(e,{href:"https://itsfoss.com/author/sarvottam/"},{default:a(()=>[...t[15]||(t[15]=[d("Sarvottam Kumar",-1)])]),_:1}),t[20]||(t[20]=d(" 选题：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[16]||(t[16]=[d("lujun9972",-1)])]),_:1}),t[21]||(t[21]=d(" 译者：",-1)),o(e,{href:"https://github.com/ywxgod"},{default:a(()=>[...t[17]||(t[17]=[d("ywxgod",-1)])]),_:1}),t[22]||(t[22]=d(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[18]||(t[18]=[d("wxy",-1)])]),_:1})]),s("p",null,[t[25]||(t[25]=d("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[23]||(t[23]=[d("LCTT",-1)])]),_:1}),t[26]||(t[26]=d(" 原创编译，",-1)),o(e,{href:"https://linux.cn/"},{default:a(()=>[...t[24]||(t[24]=[d("Linux中国",-1)])]),_:1}),t[27]||(t[27]=d(" 荣誉推出",-1))])])}const v=r(n,[["render",h]]);export{T as __pageData,v as default};
